const url="https://www.waterqualitydata.us/data/Station/search?organization=USGS-TX&huc=12030101;12030102;12030103;12030104;12030105;12030106;12030107;12030108;12030109;12030201;12030202;12030203&startDateLo=01-01-2000&startDateHi=12-31-2019&mimeType=csv&zip=no";
