{tables:{a:"d0003",r:"d0004"},sql:`SELECT 'activity_keys' AS check_name, count(*) AS n FROM (SELECT OrganizationIdentifier,ActivityIdentifier FROM a GROUP BY 1,2) UNION ALL SELECT 'result_missing_activity',count(*) FROM r LEFT JOIN a ON r.OrganizationIdentifier=a.OrganizationIdentifier AND r.ActivityIdentifier=a.ActivityIdentifier WHERE a.ActivityIdentifier IS NULL UNION ALL SELECT 'link_mismatches',count(*) FROM r JOIN a ON r.OrganizationIdentifier=a.OrganizationIdentifier AND r.ActivityIdentifier=a.ActivityIdentifier WHERE r.MonitoringLocationIdentifier<>a.MonitoringLocationIdentifier OR r.ActivityStartDate<>a.ActivityStartDate OR r.ActivityMediaName<>a.ActivityMediaName OR r.ActivityTypeCode<>a.ActivityTypeCode`},
{tables:{r:"d0004"},sql:`SELECT USGSPCode,"ResultMeasure/MeasureUnitCode",ResultStatusIdentifier,ResultValueTypeName,ResultDetectionConditionText,MeasureQualifierCode,count(*) n FROM r GROUP BY 1,2,3,4,5,6 ORDER BY 1,2,3`,limit:200},
{tables:{a:"d0003"},sql:`SELECT ActivityTypeCode,ActivityMediaName,count(*) n FROM a GROUP BY 1,2`}
].map(async q=>text(await tools.mcp__wqp_data__query_csv(q))));

function unpack(r){return JSON.parse(r.content.find(c=>c.type==="text").text)}
const qs=[
["activities",{tables:{a:"d0003"},sql:`SELECT OrganizationIdentifier,ActivityIdentifier,MonitoringLocationIdentifier,ActivityStartDate,"ActivityStartTime/Time","ActivityStartTime/TimeZoneCode","ActivityDepthHeightMeasure/MeasureValue","ActivityDepthHeightMeasure/MeasureUnitCode","ActivityTopDepthHeightMeasure/MeasureValue","ActivityTopDepthHeightMeasure/MeasureUnitCode","ActivityBottomDepthHeightMeasure/MeasureValue","ActivityBottomDepthHeightMeasure/MeasureUnitCode",ActivityRelativeDepthName FROM a WHERE ActivityMediaName='Water' AND ActivityTypeCode='Sample-Routine' ORDER BY ActivityIdentifier`,limit:2000}],
["results",{tables:{r:"d0004",a:"d0003"},sql:`SELECT r.OrganizationIdentifier,r.ActivityIdentifier,r.USGSPCode,r.ResultMeasureValue,r."ResultMeasure/MeasureUnitCode" FROM r JOIN a ON r.OrganizationIdentifier=a.OrganizationIdentifier AND r.ActivityIdentifier=a.ActivityIdentifier AND r.MonitoringLocationIdentifier=a.MonitoringLocationIdentifier AND r.ActivityStartDate=a.ActivityStartDate WHERE a.ActivityMediaName='Water' AND a.ActivityTypeCode='Sample-Routine' AND r.ResultStatusIdentifier IN ('Accepted','Final') AND r.ResultValueTypeName='Actual' AND coalesce(r.ResultDetectionConditionText,'')='' AND coalesce(r.MeasureQualifierCode,'')=''`,limit:5000}]
];
await Promise.allSettled(qs.map(async ([key,q])=>{const v=unpack(await tools.mcp__wqp_data__query_csv(q));store(key,v);text({key,...v,rows:undefined});}));

