const res=await tools.mcp__wqp_data__query_csv({tables:{t:j.id},sql:`SELECT * FROM t ORDER BY OrganizationIdentifier,ActivityIdentifier${j.key==="results"?",USGSPCode,ResultMeasureValue":""}`,limit:500,offset:j.offset});
const v=JSON.parse(res.content.find(c=>c.type==="text").text);store(j.key+"_"+j.offset,v.rows);text({key:j.key,offset:j.offset,n:v.rows.length,total:v.total_rows,error:res.isError});
}));
