text({a:a.rows.length,r:r.rows.length});

const aa=load("activities").rows, rr=load("results").rows;
const amap=new Map(aa.map(r=>[r[0]+"|"+r[1],{org:r[0],id:r[1],station:r[2],date:r[3],time:r[4],timezone:r[5],depth:r.slice(6),year:+r[3].slice(0,4),quarter:Math.floor((+r[3].slice(5,7)-1)/3)+1,values:{}}]));
const codes=["00010","00095","00300","00400"],bad=[];
for(const r of rr){
 const [org,id,code,raw,unit]=r;const a=amap.get(org+"|"+id);
 if(!a) throw Error("Missing key");
 if(!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/.test(raw.trim())||!Number.isFinite(Number(raw))){bad.push(r);continue;}
 const expected={"00010":"deg C","00095":"uS/cm @25C","00300":"mg/l","00400":"std units"};
 if(unit!==expected[code]){bad.push(r);continue;}
 (a.values[code]??=[]).push(raw);
}
const complete=[...amap.values()].filter(a=>codes.every(c=>a.values[c]&&new Set(a.values[c].map(Number)).size===1));
const conflicts=[...amap.values()].filter(a=>codes.some(c=>new Set((a.values[c]||[]).map(Number)).size>1));
store("complete",complete);
text({complete:complete.length,conflicts:conflicts.map(a=>a.id),bad,quarterCounts:complete.reduce((o,a)=>(o[a.station]=(o[a.station]||0)+1,o),{})});
const counts={};
for(const a of complete){const k=a.station+"|"+a.year+"|"+a.quarter;counts[k]=(counts[k]||0)+1;}
const supports={};
for(const s of load("ids")) supports[s]=Array.from({length:20},(_,i)=>2000+i).filter(y=>[1,2,3,4].every(q=>counts[s+"|"+y+"|"+q]));
store("supports",supports);store("quarterCounts",counts);
text(supports);
const frontierFunc=`(supports)=>{
const intervals=[];
for(let start=2000;start<=2019;start++)for(let end=start;end<=2019;end++){
const stations=Object.keys(supports).sort().filter(s=>Array.from({length:end-start+1},(_,i)=>start+i).every(y=>supports[s].includes(y)));
if(stations.length>=2)intervals.push({start,end,duration:end-start+1,coverage:stations.length,stations});
}
return intervals.filter(x=>!intervals.some(y=>y.duration>=x.duration&&y.coverage>=x.coverage&&(y.duration>x.duration||y.coverage>x.coverage)));
}`;
store("frontierFunc",frontierFunc);
const frontier=eval(frontierFunc)(supports);store("originalFrontier",frontier);text({frontier});
const changed=[];
for(const a of complete){
 const post=JSON.parse(JSON.stringify(supports));
 if(counts[a.station+"|"+a.year+"|"+a.quarter]===1)post[a.station]=post[a.station].filter(y=>y!==a.year);
 const f=eval(frontierFunc)(post);
 if(JSON.stringify(f)!==JSON.stringify(frontier))changed.push({withdrawn:a,frontier:f});
}
store("changed",changed);
text({trials:complete.length,changingTrials:changed.length,outputRows:changed.reduce((n,x)=>n+Math.max(1,x.frontier.length),0),changes:changed.map(x=>({id:x.withdrawn.id,date:x.withdrawn.date,station:x.withdrawn.station,frontier:x.frontier}))});

const complete=load("complete"),changed=load("changed");
const lex=(a,b)=>a<b?-1:a>b?1:0;
const round=(s)=>{
 if(!/^[+-]?\d+(\.\d*)?$/.test(s))throw Error("Unexpected decimal:"+s);
 let neg=s.startsWith("-"),t=s.replace(/^[+-]/,""),[whole,f=""]=t.split(".");
 let cents=BigInt(whole)*100n+BigInt((f+"00").slice(0,2));
 if(+((f+"000")[2])>=5)cents++;
 return (neg&&cents?"-":"")+(cents/100n).toString()+"."+(cents%100n).toString().padStart(2,"0");
};
const rows=[],events=[];
for(const c of changed){
 const a=c.withdrawn;
 for(const f of c.frontier){
 const pool=complete.filter(e=>!(e.org===a.org&&e.id===a.id)&&f.stations.includes(e.station)&&e.year>=f.start&&e.year<=f.end&&e.quarter===a.quarter);
 pool.sort((x,y)=>+x.values["00300"][0]-+y.values["00300"][0]||lex(x.date,y.date)||lex(x.time||"99:99:99",y.time||"99:99:99")||lex(x.station,y.station)||lex(x.id,y.id));
 const e=pool[0];
 rows.push([a.org,a.id,a.station,a.date,f.start,f.end,f.coverage,f.stations.join(";"),"Q"+a.quarter,pool.length,e.org,e.station,e.id,e.date,...["00300","00010","00095","00400"].map(k=>round(e.values[k][0]))].join("|"));
 events.push({withdrawn:a.id,start:f.start,end:f.end,count:pool.length,selected:e,ties:pool.filter(x=>+x.values["00300"][0]===+e.values["00300"][0]).map(x=>[x.id,x.date,x.time,x.station])});
 }
}
store("output",rows.join("\n"));store("events",events);
text(rows.join("\n"));text(events);

const sql=`WITH RECURSIVE years(y) AS (SELECT 2000 UNION ALL SELECT y+1 FROM years WHERE y<2019),
windows AS (SELECT b.y start_year,e.y end_year,e.y-b.y+1 duration FROM years b JOIN years e ON e.y>=b.y),
trials AS (SELECT '' id,'' station,0 year,0 quarter UNION ALL SELECT ActivityIdentifier,MonitoringLocationIdentifier,CAST(year AS INTEGER),CAST(quarter AS INTEGER) FROM c),
quarters AS (SELECT MonitoringLocationIdentifier station,CAST(year AS INTEGER) year,CAST(quarter AS INTEGER) quarter,count(*) n FROM c GROUP BY 1,2,3),
supported AS (
SELECT t.id,q.station,q.year FROM trials t CROSS JOIN quarters q
WHERE q.n-CASE WHEN t.station=q.station AND t.year=q.year AND t.quarter=q.quarter THEN 1 ELSE 0 END>0
GROUP BY 1,2,3 HAVING count(*)=4
),
members AS (
SELECT s.id,w.start_year,w.end_year,w.duration,s.station
FROM supported s JOIN windows w ON s.year BETWEEN w.start_year AND w.end_year
GROUP BY 1,2,3,4,5 HAVING count(*)=w.duration
),
designs AS (
SELECT id,start_year,end_year,duration,count(*) coverage,group_concat(station,';') stations
FROM (SELECT * FROM members ORDER BY id,start_year,end_year,station)
GROUP BY 1,2,3,4 HAVING count(*)>=2
),
frontiers AS (
SELECT d.* FROM designs d WHERE NOT EXISTS (SELECT 1 FROM designs x WHERE x.id=d.id AND x.duration>=d.duration AND x.coverage>=d.coverage AND (x.duration>d.duration OR x.coverage>d.coverage))
),
changed AS (
SELECT t.id FROM trials t WHERE t.id<>'' AND (
EXISTS (SELECT 1 FROM frontiers f WHERE f.id=t.id AND NOT EXISTS (SELECT 1 FROM frontiers o WHERE o.id='' AND o.start_year=f.start_year AND o.end_year=f.end_year AND o.stations=f.stations))
OR EXISTS (SELECT 1 FROM frontiers o WHERE o.id='' AND NOT EXISTS (SELECT 1 FROM frontiers f WHERE f.id=t.id AND o.start_year=f.start_year AND o.end_year=f.end_year AND o.stations=f.stations))
)
)
SELECT f.* FROM frontiers f JOIN changed t ON t.id=f.id ORDER BY f.id,f.start_year,f.end_year`;
store("crosscheckSql",sql);
const v=JSON.parse((await tools.mcp__wqp_data__query_csv({tables:{c:load("completeSql")},sql,limit:500})).content[0].text);
store("sqlFrontiers",v);text(v);
