text({exactMatch:JSON.stringify(v.rows)===JSON.stringify(expected)});

let sql=load("crosscheckSql").replace("CAST(quarter AS INTEGER) FROM c),","CAST(quarter AS INTEGER) FROM c WHERE ActivityIdentifier IN (SELECT ActivityIdentifier FROM critical)),");
sql=sql.replace("supported AS (","supported AS MATERIALIZED (").replace("members AS (","members AS MATERIALIZED (").replace("designs AS (","designs AS MATERIALIZED (").replace("frontiers AS (","frontiers AS MATERIALIZED (");
