text({exactMatch:JSON.stringify(v.rows)===JSON.stringify(expected)});

const sql=`WITH ranked AS (
SELECT f.id,f.start_year,f.end_year,c.ActivityIdentifier selected,c.ActivityStartDate, c."ActivityStartTime/Time",c.oxygen,c.temperature,c.conductance,c.ph,
count(*) OVER (PARTITION BY f.id,f.start_year,f.end_year) n,
row_number() OVER (PARTITION BY f.id,f.start_year,f.end_year ORDER BY CAST(c.oxygen AS REAL), c.ActivityStartDate,CASE WHEN coalesce(c."ActivityStartTime/Time",'')='' THEN 1 ELSE 0 END,c."ActivityStartTime/Time",c.MonitoringLocationIdentifier COLLATE BINARY,c.ActivityIdentifier COLLATE BINARY) rank
