AND CAST(c.year AS INTEGER) BETWEEN CAST(f.start_year AS INTEGER) AND CAST(f.end_year AS INTEGER)
AND c.quarter=w.quarter AND NOT (c.OrganizationIdentifier=w.OrganizationIdentifier AND c.ActivityIdentifier=w.ActivityIdentifier)
)
SELECT id,start_year,end_year,selected,n,ActivityStartDate,"ActivityStartTime/Time",oxygen,temperature,conductance,ph FROM ranked WHERE rank=1 ORDER BY id,CAST(start_year AS INTEGER),CAST(end_year AS INTEGER)`;
const v=JSON.parse((await tools.mcp__wqp_data__query_csv({tables:{c:load("completeSql"),f:"d0020"},sql,limit:100})).content[0].text);
text(v);
text({eventsMatch:v.rows.every((r,i)=>{const e=load("events")[i];return r[0]===e.withdrawn&&+r[1]===e.start&&+r[2]===e.end&&r[3]===e.selected.id&&+r[4]===e.count})});

const sites="USGS-08056400;USGS-08057000;USGS-08057030;USGS-08057055;USGS-08057070;USGS-08057410;USGS-08057448;USGS-08057449;USGS-08062500;USGS-08062700;USGS-08065000;USGS-08065350;USGS-08066000;USGS-08066250;USGS-08066500;USGS-08067000;USGS-08067252";store("sites",sites);
const base=`organization=USGS-TX&siteid=${sites}&startDateLo=01-01-2000&startDateHi=12-31-2019&mimeType=csv&zip=no`;store("base",base);
await Promise.allSettled(["Activity","Result"].map(async t=>{const url=`https://www.waterqualitydata.us/data/${t}/search?${base}`+(t==="Result"?"&pCode=00010;00095;00300;00400":""); const r=await tools.mcp__wqp_data__download({url});store(t,r);text({type:t,result:r});}));

const queries=[
`SELECT USGSPCode,"ResultMeasure/MeasureUnitCode" AS unit,ResultStatusIdentifier,ResultValueTypeName,ResultDetectionConditionText,MeasureQualifierCode,count(*) AS n FROM r GROUP BY 1,2,3,4,5,6 ORDER BY 1,2,3`,
`SELECT ActivityTypeCode,ActivityMediaName,count(*) AS n FROM a GROUP BY 1,2`,
`SELECT 'duplicate_activity_keys' AS check_name,count(*) AS n FROM (SELECT OrganizationIdentifier,ActivityIdentifier FROM a GROUP BY 1,2 HAVING count(*)>1) UNION ALL SELECT 'unmatched_results',count(*) FROM r LEFT JOIN a ON r.OrganizationIdentifier=a.OrganizationIdentifier AND r.ActivityIdentifier=a.ActivityIdentifier WHERE a.ActivityIdentifier IS NULL UNION ALL SELECT 'mismatched_metadata',count(*) FROM r JOIN a ON r.OrganizationIdentifier=a.OrganizationIdentifier AND r.ActivityIdentifier=a.ActivityIdentifier WHERE r.MonitoringLocationIdentifier<>a.MonitoringLocationIdentifier OR r.ActivityStartDate<>a.ActivityStartDate OR r.ActivityTypeCode<>a.ActivityTypeCode OR r.ActivityMediaName<>a.ActivityMediaName OR r."ActivityStartTime/Time"<>a."ActivityStartTime/Time"`
];text(await Promise.allSettled(queries.map(sql=>tools.mcp__wqp_data__query_csv({tables:{a:"d0003",r:"d0004"},sql,limit:200}))));

const p=load("usable");text({returned:p.rows.length,total:p.total_rows});
const batches=await Promise.allSettled(Array.from({length:Math.ceil((p.total_rows-p.rows.length)/p.rows.length)},(_,i)=>tools.mcp__wqp_data__query_csv({tables:{u:p.file_id},sql:"SELECT * FROM u",offset:(i+1)*p.rows.length,limit:p.rows.length})));
for(const r of batches) {if(r.status!=="fulfilled") throw Error(String(r.reason));const b=JSON.parse(r.value.content[0].text); p.rows.push(...b.rows);}
if(p.rows.length!==p.total_rows) throw Error("incomplete");store("usable",p);text({loaded:p.rows.length});

const p=load("usable"), byKey=new Map(), bad=[]; const units={"00010":{"deg C":1},"00095":{"uS/cm @25C":1},"00300":{"mg/l":1},"00400":{"std units":1}};
for(const row of p.rows) {
const [org,activity,station,date,time,depth,depth_unit,code,value,unit]=row;
if(!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[Ee][+-]?\d+)?$/.test(value.trim()) || !Number.isFinite(Number(value)) || !(unit in units[code])) {bad.push(row); continue;}
const key=org+"|"+activity;
if(!byKey.has(key)) byKey.set(key,{key,org,activity,station,date,time,depth,depth_unit,year:Number(date.slice(0,4)),quarter:Math.floor((Number(date.slice(5,7))-1)/3)+1,values:{}});
const a=byKey.get(key); if(!a.values[code]) a.values[code]=[];if(!a.values[code].some(x=>Number(x)===Number(value))) a.values[code].push(value);
}
const codes=Object.keys(units), complete=[...byKey.values()].filter(a=>codes.every(c=>a.values[c]?.length===1)).map(a=>({...a,values:Object.fromEntries(codes.map(c=>[c,a.values[c][0]]))}));
store("complete",complete);const counts={};for(const a of complete){const k=[a.station,a.year,a.quarter].join("|");counts[k]=(counts[k]||0)+1;}
store("counts",counts);
const masks=Object.fromEntries(load("sites").split(";").map(s=>[s,0]));
for(const s of Object.keys(masks)) for(let y=2000;y<=2019;y++) if([1,2,3,4].every(q=>counts[[s,y,q].join("|")]>0)) masks[s]|=1<<(y-2000);
store("masks",masks);
text({qualityUsableRows:p.rows.length,badNumericOrUnits:bad,activityKeysWithUsableResults:byKey.size,complete:complete.length,conflicting:[...byKey.values()].filter(a=>Object.values(a.values).some(v=>v.length>1)),support:Object.entries(masks).map(([s,m])=>({station:s,years:Array.from({length:20},(_,i)=>2000+i).filter(y=>(m&(1<<(y-2000)))>0),completeActivities:complete.filter(a=>a.station===s).length}))});

const complete=load("complete"), masks=load("masks"),counts=load("counts");
function frontier(ms){const feasible=[];for(let s=2000;s<=2019;s++)for(let e=s;e<=2019;e++){const ym=((1<<(e-s+1))-1)<<(s-2000);const cohort=Object.keys(ms).filter(k=>(ms[k]&ym)===ym).sort();if(cohort.length>=2)feasible.push({start:s,end:e,duration:e-s+1,coverage:cohort.length,cohort});}return feasible.filter(x=>!feasible.some(y=>y.duration>=x.duration&&y.coverage>=x.coverage&&(y.duration>x.duration||y.coverage>x.coverage)));}
const original=frontier(masks);const changed=[];let supportChanges=0;
for(const a of complete) {
const ms={...masks};if(counts[[a.station,a.year,a.quarter].join("|")]===1) ms[a.station]&=~(1<<(a.year-2000));
if(ms[a.station]!==masks[a.station]) supportChanges++;
const f=frontier(ms);if(JSON.stringify(f)!==JSON.stringify(original))changed.push({withdrawn:a,frontier:f});
}
store("original",original);store("changed",changed);store("frontierFunction",frontier.toString());
text({trials:complete.length,supportChanges,original,changing:changed.length,outputRows:changed.reduce((n,c)=>n+Math.max(c.frontier.length,1),0),changed:changed.map(c=>({activity:c.withdrawn.activity,date:c.withdrawn.date,station:c.withdrawn.station,frontier:c.frontier}))});

const complete=load("complete"), changed=load("changed");
const cmp=(a,b)=>a<b?-1:a>b?1:0;
function halfup(s) {
const m=/^([+-]?)(\d*)(?:\.(\d*))?$/.exec(s);if(!m)throw Error("Unsupported decimal "+s);
const frac=m[3]||"",negative=m[1]==="-"; let cents=BigInt(m[2]||"0")*100n+BigInt((frac+"00").slice(0,2));if(Number(frac[2]||"0")>=5)cents++;return (negative&&cents!==0n?"-":"")+(cents/100n)+"."+(cents%100n).toString().padStart(2,"0");
}
const rows=[],details=[];
for(const trial of changed.sort((a,b)=>cmp(a.withdrawn.activity,b.withdrawn.activity))) {
const w=trial.withdrawn;
for(const f of trial.frontier) {
const events=complete.filter(a=>a.key!==w.key&&f.cohort.includes(a.station)&&a.year>=f.start&&a.year<=f.end&&a.quarter===w.quarter);
events.sort((a,b)=>Number(a.values["00300"])-Number(b.values["00300"])||cmp(a.date,b.date)||cmp(a.time||"~",b.time||"~")||cmp(a.station,b.station)||cmp(a.activity,b.activity));
const a=events[0];
rows.push([w.org,w.activity,w.station,w.date,f.start,f.end,f.coverage,f.cohort.join(";"),"Q"+w.quarter,events.length,a.org,a.station,a.activity,a.date,...["00300","00010","00095","00400"].map(c=>halfup(a.values[c]))].join("|"));
details.push({withdrawal:w.activity,interval:[f.start,f.end],count:events.length,selected:a,tiedLowest:events.filter(e=>Number(e.values["00300"])===Number(a.values["00300"])).map(e=>({activity:e.activity,date:e.date,time:e.time,station:e.station}))});
}}
store("finalRows",rows);store("selectionDetails",details);text(rows.join("\n"));text(details);

const sql=`WITH q AS (SELECT org,station,CAST(substr(date,1,4) AS INTEGER) AS yr,(CAST(substr(date,6,2) AS INTEGER)-1)/3+1 AS qt,count(*) AS n FROM a GROUP BY 1,2,3,4),
scenarios AS (SELECT org,activity,station,CAST(substr(date,1,4) AS INTEGER) AS yr,(CAST(substr(date,6,2) AS INTEGER)-1)/3+1 AS qt FROM a UNION ALL SELECT 'USGS-TX','BASELINE','',0,0)
SELECT w.activity AS withdrawal,q.org,q.station,q.yr AS year
FROM scenarios w CROSS JOIN q
GROUP BY w.activity,q.org,q.station,q.yr
HAVING count(*)=4 AND min(q.n-CASE WHEN w.org=q.org AND w.station=q.station AND w.yr=q.yr AND w.qt=q.qt THEN 1 ELSE 0 END)>0`;
text(await tools.mcp__wqp_data__query_csv({tables:{a:"d0015"},sql,limit:2}));

const sql=`WITH signatures AS (SELECT withdrawal,group_concat(start_year||','||end_year||','||cohort,'|') AS sig FROM (SELECT * FROM f ORDER BY withdrawal,CAST(start_year AS INTEGER),CAST(end_year AS INTEGER)) GROUP BY withdrawal),
changing AS (SELECT withdrawal FROM signatures WHERE sig<>(SELECT sig FROM signatures WHERE withdrawal='BASELINE')),
ranked AS (
SELECT w.org AS withdrawn_org,w.activity AS withdrawn_activity,w.station AS withdrawn_station,w.date AS withdrawn_date,
CAST(f.start_year AS INTEGER) AS start_year,CAST(f.end_year AS INTEGER) AS end_year,CAST(f.coverage AS INTEGER) AS coverage,f.cohort,'Q'||w.quarter AS quarter,
