function supports(activities){
const counts={};
for(const a of activities){const k=a.station+"|"+a.year;counts[k]??=[0,0,0,0];counts[k][a.quarter-1]++;}
return new Set(Object.keys(counts).filter(k=>counts[k].every(n=>n>0)));
}
function frontier(support,stations){
const intervals=[];
for(let start=2000;start<=2019;start++){
let cohort=stations.slice();
for(let end=start;end<=2019;end++){
cohort=cohort.filter(s=>support.has(s+"|"+end));
if(cohort.length>=2)intervals.push({start,end,duration:end-start+1,coverage:cohort.length,cohort:cohort.slice()});
}
}
return intervals.filter(y=>!intervals.some(x=>x.duration>=y.duration&&x.coverage>=y.coverage&&(x.duration>y.duration||x.coverage>y.coverage)));
}
function identity(f){return JSON.stringify(f.map(x=>[x.start,x.end,x.cohort]));}
`);
const run=new Function("activities","stations",load("frontierCode")+`
const support=supports(activities),original=frontier(support,stations),changed=[];
for(const a of activities){
const trial=activities.filter(b=>b.org!==a.org||b.id!==a.id);
const post=frontier(supports(trial),stations);
if(identity(post)!==identity(original))changed.push({withdrawn:a,frontier:post});
}
return {original,changed,supportedYears:stations.map(s=>[s,Array.from({length:20},(_,i)=>i+2000).filter(y=>support.has(s+"|"+y))])};
`);
const out=run(load("complete"),load("stations").map(s=>s[1]));store("audit",out);text({original:out.original,supportedYears:out.supportedYears,changed:out.changed.map(c=>({id:c.withdrawn.id,date:c.withdrawn.date,station:c.withdrawn.station,frontier:c.frontier})),rows:out.changed.reduce((s,c)=>s+Math.max(1,c.frontier.length),0)});

