for(const d of all)byCoverage[d.coverage]=Math.max(byCoverage[d.coverage]||0,d.duration);
return all.filter(d=>!Object.entries(byCoverage).some(([n,years])=>(Number(n)>d.coverage&&years>=d.duration)||(Number(n)===d.coverage&&years>d.duration)));
}
