function halfUp(raw){
 let s=raw.trim(),neg=s.startsWith("-");s=s.replace(/^[+-]/,"");
 let [i="",f=""]=s.split(".");if(!/^\d*$/.test(i+f))throw Error("Unsupported decimal "+raw);
 f=f.padEnd(3,"0");let n=BigInt(i||0)*100n+BigInt(f.slice(0,2));if(f[2]>="5")n++;
 return (neg&&n!==0n?"-":"")+(n/100n)+"."+(n%100n).toString().padStart(2,"0");
}
